`timescale 1 ns / 10 ps

module AvgPoolSingle_TB ();
  
reg [28*28*16-1:0] inAvg;
wire [14*14*16-1:0] outAvg;

integer i,j;
integer fid1,fid2;
initial fid1 = $fopen("avpool.in");
initial fid2 = $fopen("avpool.out");



initial begin
    #0
    inAvg = 12544';
    #10
    for(i=28*28-1;i>=0;i=i-1) begin
        $display(inAvg[i*16+:16]);
        if(i%28==27)begin
            $fwrite(fid1,"\n");
        end
        else begin
            $fwrite(fid1,"%H ",inAvg[i*16+:16]);
        end       
    end

    for(j=14*14-1;j>=0;j=j-1) begin
        $display(outAvg[j*16+:16]);
        if(j%14==13) begin
            $fwrite(fid2,"\n");
        end
        else begin
            $fwrite(fid2,"%H ",outAvg[j*16+:16]);
        end       
    end

    #20


    $stop;





end
avgPoolSingle UUT
  (
    .aPoolIn(inAvg),
    .aPoolOut(outAvg)
  );
endmodule
    
